*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', sans-serif;
    h1, h2, h3, h4, h5, h6 { font-family: 'Space Grotesk', sans-serif; }
      color: #e0e0e0;
      background: #0a0a0a;
      line-height: 1.6;
      overflow-x: hidden;
    }
    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }

    :root {
      --accent: #e53935;
      --accent-light: #ff6b6b;
      --accent-dark: #b71c1c;
      --bg-card: #111;
      --bg-card-hover: #1a1a1a;
      --text-muted: #888;
      --radius: 16px;
      --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

    h1, h2, h3, h4 { font-weight: 800; line-height: 1.15; }
    h1 { font-size: clamp(2.5rem, 6vw, 4.5rem); }
    h2 { font-size: clamp(1.8rem, 4vw, 2.8rem); margin-bottom: 16px; }
    h3 { font-size: 1.35rem; }

    .gradient-text {
      background: linear-gradient(135deg, var(--accent), #ff8a80);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .section-subtitle {
      color: var(--text-muted);
      max-width: 600px;
      margin: 0 auto 48px;
      text-align: center;
      font-size: 1.05rem;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 14px 32px;
      border-radius: 50px;
      font-weight: 700;
      font-size: 1rem;
      border: none;
      cursor: pointer;
      transition: var(--transition);
      text-align: center;
    }
    .btn-primary {
      background: linear-gradient(135deg, var(--accent), var(--accent-dark));
      color: #fff;
    }
    .btn-primary:hover {
      transform: translateY(-3px);
      box-shadow: 0 12px 32px rgba(229,57,53,.35);
    }
    .btn-outline {
      background: transparent;
      color: var(--accent-light);
      border: 2px solid var(--accent);
    }
    .btn-outline:hover {
      background: var(--accent);
      color: #fff;
      transform: translateY(-3px);
    }
    .btn-whatsapp {
      background: #25D366;
      color: #fff;
    }
    .btn-whatsapp:hover {
      background: #1da851;
      transform: translateY(-3px);
      box-shadow: 0 12px 32px rgba(37,211,102,.3);
    }

    nav {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 100;
      background: rgba(10,10,10,.88);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      border-bottom: 1px solid rgba(255,255,255,.06);
      padding: 14px 0;
    }
    nav .container { display: flex; align-items: center; justify-content: space-between; }
    .nav-logo {
      font-weight: 800; font-size: 1.3rem; color: #fff;
      display: flex; align-items: center; gap: 8px;
    }
    .nav-logo .logo-icon {
      display: inline-flex; width: 34px; height: 34px;
      border-radius: 8px;
      background: linear-gradient(135deg, var(--accent), #8b0000);
      align-items: center; justify-content: center; font-size: 1.1rem;
    }
    .nav-links { display: flex; gap: 32px; list-style: none; align-items: center; }
    .nav-links a {
      color: rgba(255,255,255,.7); font-size: .9rem; font-weight: 500;
      transition: color .3s; position: relative;
    }
    .nav-links a::after {
      content: ''; position: absolute; bottom: -4px; left: 0;
      width: 0; height: 2px; background: var(--accent); transition: width .3s;
    }
    .nav-links a:hover { color: #fff; }
    .nav-links a:hover::after { width: 100%; }
    .nav-toggle {
      display: none; flex-direction: column; gap: 5px;
      cursor: pointer; background: none; border: none; padding: 4px;
    }
    .nav-toggle span { display: block; width: 26px; height: 2.5px; background: #fff; border-radius: 2px; transition: var(--transition); }

    .hero {
      min-height: 100vh;
      display: flex; align-items: center; justify-content: center;
      text-align: center;
      position: relative;
      overflow: hidden;
      padding-top: 80px;
    }
    .hero::before {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(135deg, rgba(10,10,10,.85), rgba(10,10,10,.6)),
                  url('img/hero.webp') center/cover fixed;
      z-index: 0;
    }
    .hero::after {
      content: ''; position: absolute; top: -50%; left: -50%;
      width: 200%; height: 200%;
      background: radial-gradient(circle at 30% 40%, rgba(229,57,53,.08) 0%, transparent 50%);
      pointer-events: none;
    }
    .hero-content { position: relative; z-index: 2; max-width: 750px; padding: 20px; }
    .hero-badge {
      display: inline-block;
      background: rgba(229,57,53,.15);
      backdrop-filter: blur(6px);
      padding: 8px 22px; border-radius: 50px; font-size: .82rem;
      letter-spacing: 1px; text-transform: uppercase; margin-bottom: 20px;
      border: 1px solid rgba(229,57,53,.2); color: var(--accent-light);
    }
    .hero h1 { margin-bottom: 12px; }
    .hero .tagline {
      font-size: clamp(1.1rem, 2vw, 1.4rem); font-weight: 400;
      color: rgba(255,255,255,.7); margin-bottom: 12px;
    }
    .hero .subtitle {
      font-size: 1.05rem; color: var(--text-muted);
      margin-bottom: 36px; max-width: 600px; margin-left: auto; margin-right: auto;
    }
    .hero-actions { display: flex; flex-wrap: wrap; gap: 16px; justify-content: center; }
    .hero-stats { display: flex; gap: 40px; justify-content: center; margin-top: 48px; flex-wrap: wrap; }
    .hero-stat { text-align: center; }
    .hero-stat-num { font-size: 2rem; font-weight: 800; color: #fff; }
    .hero-stat-num span { color: var(--accent-light); }
    .hero-stat-label { font-size: .82rem; color: var(--text-muted); margin-top: 2px; }

    section { padding: 100px 0; }
    .section-title { text-align: center; margin-bottom: 12px; }
    .section-dark { background: #0d0d0d; }

    .dark-card {
      background: var(--bg-card);
      border-radius: var(--radius);
      padding: 32px;
      border: 1px solid rgba(255,255,255,.04);
      transition: var(--transition);
    }
    .dark-card:hover {
      background: var(--bg-card-hover);
      border-color: rgba(229,57,53,.15);
      transform: translateY(-4px);
      box-shadow: 0 20px 60px rgba(0,0,0,.3);
    }

    .about-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
    .about-image { border-radius: var(--radius); overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,.3); }
    .about-image img { width: 100%; height: 450px; object-fit: cover; transition: transform .6s; }
    .about-image:hover img { transform: scale(1.04); }
    .about-text p { margin-bottom: 16px; color: rgba(255,255,255,.7); font-size: 1.05rem; }
    .about-features { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 24px; }
    .about-feature { display: flex; align-items: center; gap: 12px; font-weight: 500; }
    .about-feature .icon {
      width: 40px; height: 40px; border-radius: 12px;
      display: flex; align-items: center; justify-content: center;
      font-size: 1.2rem; background: rgba(229,57,53,.12); color: var(--accent-light);
    }

    .menu-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 28px; }
    .menu-card { text-align: center; padding: 40px 28px; }
    .menu-card .menu-icon {
      width: 80px; height: 80px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 2.4rem; margin: 0 auto 16px;
    }
    .menu-card h3 { margin-bottom: 8px; }
    .menu-card p { color: var(--text-muted); font-size: .92rem; margin-bottom: 12px; }
    .menu-card .price { font-weight: 700; font-size: 1.2rem; color: var(--accent-light); }

    .gallery-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; }
    .gallery-item { border-radius: var(--radius); overflow: hidden; aspect-ratio: 3/2; }
    .gallery-item img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s; }
    .gallery-item:hover img { transform: scale(1.06); }

    .location-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: start; }
    .location-detail { display: flex; gap: 16px; margin-bottom: 20px; }
    .location-detail .icon {
      flex-shrink: 0; width: 48px; height: 48px; border-radius: 14px;
      display: flex; align-items: center; justify-content: center; font-size: 1.3rem;
    }
    .location-detail .icon.red { background: rgba(229,57,53,.12); color: var(--accent-light); }
    .location-detail .icon.green { background: rgba(37,211,102,.1); color: #25D366; }
    .location-detail .icon.blue { background: rgba(66,165,245,.1); color: #42a5f5; }
    .location-detail .info-label { font-size: .8rem; text-transform: uppercase; letter-spacing: 1px; color: #888; font-weight: 600; }
    .location-detail .info-value { font-weight: 600; font-size: 1.05rem; margin-top: 2px; color: rgba(255,255,255,.85); }
    .location-map { border-radius: var(--radius); overflow: hidden; box-shadow: 0 8px 30px rgba(0,0,0,.2); }
    .location-map iframe { width: 100%; height: 350px; border: none; }

    .cta-section { text-align: center; position: relative; overflow: hidden; }
    .cta-section::before {
      content: ''; position: absolute; top: -50%; left: -50%;
      width: 200%; height: 200%;
      background: radial-gradient(circle at 50% 50%, rgba(229,57,53,.06) 0%, transparent 50%);
      pointer-events: none;
    }
    .cta-section .container { position: relative; z-index: 2; }
    .cta-section h2 { font-size: clamp(1.8rem, 3.5vw, 2.6rem); }
    .cta-section p { color: var(--text-muted); max-width: 550px; margin: 0 auto 36px; font-size: 1.05rem; }
    .cta-actions { display: flex; flex-wrap: wrap; gap: 16px; justify-content: center; }
    .social-links { display: flex; justify-content: center; gap: 20px; margin-top: 24px; }
    .social-link {
      width: 52px; height: 52px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 1.4rem; transition: all .3s;
      background: rgba(255,255,255,.06); color: rgba(255,255,255,.7);
    }
    .social-link:hover { transform: translateY(-4px); background: var(--accent); color: #fff; }

    footer { border-top: 1px solid rgba(255,255,255,.04); text-align: center; padding: 40px 0; color: rgba(255,255,255,.35); font-size: .85rem; }
    footer a { color: rgba(255,255,255,.5); }
    footer a:hover { color: var(--accent-light); }

    @media (max-width: 768px) {
      .nav-links {
        display: none; position: absolute; top: 100%; left: 0; right: 0;
        background: rgba(10,10,10,.97); flex-direction: column; padding: 20px 24px; gap: 16px;
        border-bottom: 1px solid rgba(255,255,255,.06);
      }
      .nav-links.open { display: flex; }
      .nav-links .btn { width: 100%; text-align: center; }
      .nav-toggle { display: flex; }
      section { padding: 64px 0; }
      .hero { min-height: 90vh; }
      .about-grid, .location-grid { grid-template-columns: 1fr; gap: 32px; }
      .about-image img { height: 280px; }
      .about-features { grid-template-columns: 1fr; }
      .hero-stats { gap: 24px; }
    }
    @media (max-width: 480px) {
      .hero-actions, .cta-actions { flex-direction: column; align-items: center; }
      .hero-actions .btn, .cta-actions .btn { width: 100%; justify-content: center; }
    }

    /* WhatsApp Flotante */
    .wa-float {
      position: fixed;
      bottom: 20px;
      right: 20px;
      width: 56px;
      height: 56px;
      background: #25D366;
      color: #fff;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 28px;
      box-shadow: 0 4px 20px rgba(37,211,102,.4);
      z-index: 9999;
      transition: transform .2s, box-shadow .2s;
    }
    .wa-float:hover {
      transform: scale(1.1);
      box-shadow: 0 6px 28px rgba(37,211,102,.6);
    }

